-- ══════════════════════════════════════════════════════════════
-- Migration 0238 — Knowledge Stack: das Erklär-Quiz
-- ══════════════════════════════════════════════════════════════
--
-- „Knowledge Stack: Was das Quiz alles kann“ — 20 Fragen, die alle
-- Funktionen zeigen: Raum und Lobby, Wesen und Emotes, Vorlesezeit,
-- Auflösung, Siegerehrung, Profilbild, die vier Fragetypen (die im
-- Quiz selbst vorkommen), Editor, Text-Import, Status im Katalog,
-- Raum-Modus „gemeinsam erstellen“, hell/dunkel. Jede Frage hat als
-- Foto ein Bildschirmfoto der echten Oberfläche.
--
-- Eine Vorlage (is_template, visibility 'hub'): sichtbar für jede
-- freigeschaltete Lehrkraft (ks_catalog_can_see), niemandem gehörend,
-- bearbeitet wird sie nur hier. „⧉ Kopie“ im Katalog legt eine eigene an.
--
-- ERZEUGT von MPSkills/tools/KnowledgeStack/tools/anleitung.mjs — nicht
-- von Hand ändern, sondern dort und neu laufen lassen.
-- Braucht 0186 (Fotos), 0194 (Katalog), 0217 (Fragetypen).
-- Idempotent: on conflict, die Fragen werden ersetzt.
-- ══════════════════════════════════════════════════════════════

insert into ks_catalogs (id, owner_id, school_id, title, subject, is_template,
                         visibility, thumbnail, thumb_custom, updated_at)
values ('00000000-0000-4000-8000-000000000238', null, null, 'Knowledge Stack: Was das Quiz alles kann', 'Tablet & Medien', true,
        'hub', 'data:image/jpeg;base64,', true, now())
on conflict (id) do update set
  title        = excluded.title,
  subject      = excluded.subject,
  is_template  = true,
  visibility   = 'hub',
  thumbnail    = excluded.thumbnail,
  thumb_custom = true,
  updated_at   = now();

delete from ks_questions where catalog_id = '00000000-0000-4000-8000-000000000238';

insert into ks_questions (catalog_id, sort_order, kind, question_text,
                          options, correct_idx, correct_indices,
                          time_limit_sec, explanation, scale,
                          image_name, image) values
('00000000-0000-4000-8000-000000000238', 0, 'mc', 'Was ist Knowledge Stack?',
 '["Ein Live-Quiz: Fragen am Beamer, Antworten auf den Tablets","Ein Karteikarten-Programm zum Allein-Lernen","Eine Abgabe-Box für Hausaufgaben","Ein Chat für die Klasse"]'::jsonb, 0, array[0]::smallint[],
 25, 'Die Lehrkraft öffnet in MPSkills einen Raum, die Klasse tritt per Code oder QR-Code bei. Gespielt wird gemeinsam und live.', null,
 'beam_frage.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 1, 'tf', 'Auf dem Tablet steht die Frage noch einmal zum Nachlesen.',
 '["Wahr","Falsch"]'::jsonb, 1, array[1]::smallint[],
 15, 'Falsch: Die Frage steht nur am Beamer, das Tablet zeigt nur die farbigen Antwortfelder. So schauen alle nach vorn.', null,
 'tab_frage.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 2, 'mc', 'Was machen die Schülerinnen und Schüler in der Lobby, bevor es losgeht?',
 '["Sie suchen sich ein Wesen aus und schicken Emotes","Sie beantworten schon die erste Frage","Sie stellen die Zeit für jede Frage ein","Nichts – das Tablet bleibt schwarz"]'::jsonb, 0, array[0]::smallint[],
 20, 'Jedes Kind wählt sein Wesen und eine Farbe. Mit den Emotes (winken, springen, jubeln, tanzen, schlafen) bewegt es sich am Beamer.', null,
 'tab_lobby.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 3, 'scale', 'Wie viele verschiedene Wesen gibt es zur Auswahl?',
 '[]'::jsonb, 0, array[0]::smallint[],
 25, 'Es sind 40 Wesen, jedes in 3 Farben. Am Beamer fallen sie auf die Wiese und laufen herum. – Das hier war übrigens eine Skala-Frage.', '{"min":0,"max":100,"target":40,"step":1,"unit":"Wesen"}'::jsonb,
 'beam_lobby.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 4, 'mc', 'Was passiert am Anfang jeder Frage, bevor die Antworten erscheinen?',
 '["5 Sekunden Vorlesezeit, dann erscheinen die Antworten überall gleichzeitig","Die Lehrkraft muss jede Antwort einzeln freigeben","Die Schnellsten sehen die Antworten zuerst","Nichts, die Uhr läuft sofort"]'::jsonb, 0, array[0]::smallint[],
 20, 'Erst wird die Frage gelesen, dann decken Beamer und alle Tablets im selben Moment auf. Langsames WLAN ist kein Nachteil.', null,
 'beam_lesen.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 5, 'bet', 'Was bringt bei einer normalen Auswahlfrage Punkte? Setze deine Münzen!',
 '["Richtig antworten","Schnell antworten","Mehrmals hintereinander richtig","Die Farbe der Antwort"]'::jsonb, 0, array[0, 1, 2]::smallint[],
 30, 'Richtig, schnell und eine Serie zählen. Das war eine Münzen-Frage: 5 Münzen à 200 Punkte auf die Antworten ziehen oder tippen – umsetzen geht, bis die Uhr abläuft.', null,
 'tab_wette.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 6, 'mc', 'Was zeigt der Beamer nach jeder Frage (Auflösung)?',
 '["Wie viele was gewählt haben, die Top 5 und eine Erklärung","Nur die richtige Antwort","Die Namen aller, die falsch lagen","Die Antworten jedes einzelnen Kindes"]'::jsonb, 0, array[0]::smallint[],
 20, 'Füllstände zeigen die Verteilung, die fünf Ersten tauschen die Plätze, darunter steht die Erklärung – so wie dieser Text.', null,
 'beam_reveal.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 7, 'mc', 'Was sieht ein Kind nach der Frage auf seinem Tablet?',
 '["Richtig oder falsch, seine Punkte und wer direkt vor und hinter ihm liegt","Die komplette Rangliste der Klasse","Nur „Weiter“","Die Lösung aller Fragen"]'::jsonb, 0, array[0]::smallint[],
 20, 'Jedes Kind sieht seinen Platz zwischen dem Nachbarn davor und dahinter. Wer falsch lag, dessen Wesen ist kurz traurig.', null,
 'tab_reveal.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 8, 'tf', 'Es gibt auch Wahr/Falsch-Fragen – so wie diese hier.',
 '["Wahr","Falsch"]'::jsonb, 0, array[0]::smallint[],
 15, 'Wahr. Die Knöpfe heißen „Wahr“ und „Falsch“, lassen sich aber umbenennen (z. B. Ja/Nein).', null,
 'beam_tf.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 9, 'tf', 'Bei einer Skala-Frage bekommt nur Punkte, wer die Zahl genau trifft.',
 '["Wahr","Falsch"]'::jsonb, 1, array[1]::smallint[],
 15, 'Falsch. Genau getroffen gibt 1000 Punkte, je weiter weg, desto weniger. Erst ab 30 % der Spanne daneben gibt es 0.', null,
 'beam_skala.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 10, 'mc', 'Bei einer Münzen-Frage dürfen mehrere Antworten richtig sein. Was zählt der Beamer in der Auflösung?',
 '["Die gesetzten Münzen je Antwort","Die Köpfe je Antwort","Nur die Zeit","Gar nichts"]'::jsonb, 0, array[0]::smallint[],
 20, 'Bei Münzen zählen die Füllstände Münzen statt Köpfe. Jede Münze auf einer richtigen Antwort bringt 200 Punkte.', null,
 'beam_wette.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 11, 'mc', 'Wie endet ein Quiz?',
 '["Siegerehrung: Platz 3, 2 und mit Trommelwirbel Platz 1 springen aufs Treppchen","Der Beamer wird einfach schwarz","Alle bekommen eine Note","Die Punkte werden per Mail verschickt"]'::jsonb, 0, array[0]::smallint[],
 20, 'Danach gibt es Konfetti, alle klatschen. „↺ Nochmal“ startet dasselbe Quiz von vorn.', null,
 'beam_ende.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 12, 'tf', 'Wer angemeldet mitspielt, kann sein Quiz-Wesen danach als Profilbild bekommen.',
 '["Wahr","Falsch"]'::jsonb, 0, array[0]::smallint[],
 15, 'Wahr. Wer mindestens eine Antwort gegeben hat, schaltet sein Wesen als Profilbild frei. Platz 1 bekommt zusätzlich die Gold-Fassung.', null,
 'tab_sieg.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 13, 'mc', 'Wo schreibt man ein Quiz, ohne dafür einen Raum zu öffnen?',
 '["Im „Quiz-Editor“ auf der Knowledge-Stack-Kachel","Nur im Raum während des Spiels","In einer Word-Datei, die man hochlädt","Das geht nur über den Admin"]'::jsonb, 0, array[0]::smallint[],
 20, 'Der Quiz-Editor öffnet den Katalog: eigene Quizze, die der Schule und alle geteilten, mit Suche und Filtern nach Themenfeld.', null,
 'ed_liste.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 14, 'mc', 'Welche Fragetypen bietet der Editor an?',
 '["Auswahl, Wahr/Falsch, Skala und Münzen setzen","Nur Auswahl mit vier Antworten","Nur Freitext","Auswahl und Lückentext"]'::jsonb, 0, array[0]::smallint[],
 25, 'Der Typ wird je Frage über der Frage gewählt. Bei der Auswahl dürfen auch mehrere Antworten richtig sein, die Zeit je Frage ist einstellbar.', null,
 'ed_edit.jpg', 'data:image/jpeg;base64,'),

('00000000-0000-4000-8000-000000000238', 15, 'tf', 'Ein Foto an einer Frage sehen auch die Kinder auf ihren Tablets.',
 '["Wahr","Falsch"]'::jsonb, 1, array[1]::smallint[],
 15, 'Falsch – Fotos stehen nur am Beamer zwischen Frage und Antworten. Die Vorschau im Editor zeigt, wie es dort aussieht.', null,
